  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.note-body {
  margin: 0.5rem 0 0;
  overflow-wrap: anywhere;
}

.note-body a {
  color: var(--accent);
}

.note-time {
  display: block;
  margin-top: 0.6rem;
  font-size: 0.78rem;
  color: var(--muted);
}

.empty {
  margin: 0;
  padding: 1.5rem;
  text-align: center;
  color: var(--muted);
  border: 1px dashed var(--line);
  border-radius: 12px;
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}

