import { spawn } from 'node:child_process';
import { chromium } from '@playwright/test';

const dir = '/workspace/benchmark/runs/lanes/lane-2/arm-a-vibe';
const port = 4911;
const server = spawn('node', [dir + '/server.mjs', '--port', String(port)], { cwd: dir, stdio: 'ignore' });
await new Promise((r) => setTimeout(r, 600));
const base = `http://127.0.0.1:${port}/`;

let pass = 0, fail = 0;
const ok = (name, cond, extra = '') => { cond ? pass++ : fail++; console.log(`${cond ? 'ok  ' : 'FAIL'} ${name}${cond ? '' : '  << ' + extra}`); };

const browser = await chromium.launch();
const ctx = await browser.newContext();
const page = await ctx.newPage();
const errors = [];
page.on('pageerror', (e) => errors.push('pageerror: ' + e.message));
page.on('console', (m) => m.type() === 'error' && errors.push('console: ' + m.text()));
await page.exposeFunction('__xss', () => { errors.push('XSS EXECUTED'); });
await page.addInitScript(() => { window.alert = () => window.__xss(); window.__hit = () => window.__xss(); });

// ---- seed + feed
await page.goto(base, { waitUntil: 'load' });
ok('seeds 6 notes', (await page.$$('#feed article.note')).length === 6);
const ids = await page.$$eval('#feed article.note', (a) => a.map((n) => n.dataset.noteId));
ok('newest first', JSON.stringify(ids) === JSON.stringify(['6','5','4','3','2','1']), ids.join(','));
ok('.note-title/.note-body present', (await page.$$('.note-title')).length === 6 && (await page.$$('.note-body')).length === 6);
ok('avatars only where given', (await page.$$('img.note-avatar')).length === 3);

// ---- rich text renders
ok('bold renders as <b>', await page.$eval('[data-note-id="1"] .note-body b', (e) => e.textContent.includes('OWASP')));
ok('italic renders as <i>', await page.$eval('[data-note-id="2"] .note-body i', (e) => e.textContent === 'Ribeira'));
ok('<br> renders', (await page.$$('[data-note-id="1"] .note-body br')).length === 1);
const href = await page.$eval('[data-note-id="4"] .note-body a', (e) => e.getAttribute('href'));
ok('link clickable', href === 'https://www.livrarialello.pt/', String(href));

// ---- search
await page.fill('#search', 'douro');
await page.waitForTimeout(120);
ok('search filters (case-insensitive)', (await page.$$('#feed article.note')).length === 3, String((await page.$$('#feed article.note')).length));
ok('results line text', (await page.textContent('#results-line')) === 'results for "douro"', await page.textContent('#results-line'));
ok('fragment has q', page.url().endsWith('#q=douro'), page.url());
await page.fill('#search', '');
await page.waitForTimeout(120);
ok('empty query clears results line', (await page.textContent('#results-line')) === '');
ok('empty query clears fragment', !page.url().includes('#'), page.url());

// ---- selection + deep link
await page.fill('#search', 'port');
await page.waitForTimeout(120);
await page.click('[data-note-id="3"] .note-title').catch(() => {});
let count = (await page.$$('#feed article.note')).length;
await page.fill('#search', '');
await page.waitForTimeout(100);
await page.click('[data-note-id="3"] .note-title');
await page.waitForTimeout(120);
ok('selected note aria-current', (await page.getAttribute('[data-note-id="3"]', 'aria-current')) === 'true');
ok('only one selected', (await page.$$('[aria-current="true"]')).length === 1);
ok('fragment #note=3', page.url().endsWith('#note=3'), page.url());
await page.fill('#search', 'port');
await page.waitForTimeout(120);
ok('combined fragment #q=port&note=3', page.url().endsWith('#q=port&note=3'), page.url());

// ---- restore on reload
await page.goto(base + '#q=port&note=3', { waitUntil: 'load' });
await page.waitForTimeout(200);
ok('restores query on load', (await page.inputValue('#search')) === 'port');
ok('restores results line', (await page.textContent('#results-line')) === 'results for "port"');
ok('restores selection', (await page.getAttribute('[data-note-id="3"]', 'aria-current')) === 'true');
ok('reload keeps fragment', page.url().endsWith('#q=port&note=3'), page.url());

// ---- add note + persistence
await page.goto(base, { waitUntil: 'load' });
await page.fill('#title', 'Ponte Luis I');
await page.fill('#body', 'Cross <b>on foot</b>.\nLine two.');
await page.fill('#avatar', 'https://example.test/a.png');
await page.click('#note-form button[type=submit]');
await page.waitForTimeout(150);
ok('new note is first', (await page.$eval('#feed article.note', (n) => n.dataset.noteId)) === '7');
ok('id continues sequence', !!(await page.$('[data-note-id="7"]')));
ok('form cleared', (await page.inputValue('#title')) === '' && (await page.inputValue('#body')) === '' && (await page.inputValue('#avatar')) === '');
ok('newline -> <br>', (await page.$$('[data-note-id="7"] .note-body br')).length === 1);
ok('new note bold renders', await page.$eval('[data-note-id="7"] .note-body b', (e) => e.textContent === 'on foot'));
ok('new note avatar', (await page.getAttribute('[data-note-id="7"] img.note-avatar', 'src')) === 'https://example.test/a.png');
await page.reload({ waitUntil: 'load' });
await page.waitForTimeout(200);
ok('persists across reload', (await page.$$('#feed article.note')).length === 7);

// ---- injection surface
const payloads = [
  ['script tag', '<script>alert(1)</script>'],
  ['img onerror', '<img src=x onerror="__hit()">'],
  ['svg onload', '<svg onload=__hit()>'],
  ['b with onclick', '<b onclick="__hit()" onmouseover="__hit()">hi</b>'],
  ['javascript: href', '<a href="javascript:__hit()">x</a>'],
  ['entity-hidden scheme', '<a href="javascript&#58;__hit()">x</a>'],
  ['tab-split scheme', '<a href="java\tscript:__hit()">x</a>'],
  ['case + spaces', '<A HREF=" JaVaScRiPt:__hit()">x</A>'],
  ['iframe srcdoc', '<iframe srcdoc="<script>parent.__hit()</script>"></iframe>'],
  ['unclosed bold breakout', '<b>bold</b><style>*{}</style>'],
  ['form action', '<form action="javascript:__hit()"><button>go</button></form>'],
];
for (const [name, payload] of payloads) {
  await page.fill('#title', 'T ' + name);
  await page.fill('#body', payload);
  await page.click('#note-form button[type=submit]');
  await page.waitForTimeout(60);
}
await page.waitForTimeout(400);
const nid = await page.$eval('#feed article.note', (n) => n.dataset.noteId);
const bad = await page.$$eval('#feed .note-body', (bodies) =>
  bodies.flatMap((b) => [...b.querySelectorAll('*')].map((e) => e.tagName.toLowerCase() + ':' + [...e.attributes].map((a) => a.name + '=' + a.value).join('|'))),
);
const disallowedEl = bad.filter((s) => !/^(b|strong|i|em|a|br):/.test(s));
ok('no disallowed elements rendered', disallowedEl.length === 0, disallowedEl.join(' ; '));
const eventAttrs = bad.filter((s) => /\bon[a-z]+=/.test(s));
ok('no event-handler attributes', eventAttrs.length === 0, eventAttrs.join(' ; '));
const jsHrefs = await page.$$eval('#feed a', (as) => as.map((a) => a.protocol + '|' + a.getAttribute('href')));
ok('no javascript: hrefs', !jsHrefs.some((h) => h.startsWith('javascript:')), jsHrefs.join(' ; '));
ok('payloads shown as text', await page.$eval('#feed .note-body', (b) => b.textContent.length > 0));
ok('no script executed', !errors.includes('XSS EXECUTED'), errors.join(' ; '));

// avatar scheme
await page.fill('#title', 'bad avatar');
await page.fill('#body', 'x');
await page.fill('#avatar', 'javascript:__hit()');
await page.click('#note-form button[type=submit]');
await page.waitForTimeout(150);
ok('unsafe avatar dropped', (await page.$('#feed article.note img.note-avatar')) === null);

// hostile localStorage
await page.evaluate(() => localStorage.setItem('porto-notes:v1', '{"not":"an array"}'));
await page.reload({ waitUntil: 'load' });
await page.waitForTimeout(200);
ok('corrupt storage falls back to seed', (await page.$$('#feed article.note')).length === 6);
await page.evaluate(() => localStorage.setItem('porto-notes:v1', 'not json at all'));
await page.reload({ waitUntil: 'load' });
await page.waitForTimeout(200);
ok('unparseable storage falls back to seed', (await page.$$('#feed article.note')).length === 6);

ok('no console/page errors', errors.length === 0, errors.join(' ; '));

await browser.close();
server.kill();
console.log(`\n${pass} passed, ${fail} failed`);
process.exit(fail ? 1 : 0);

