console.log('hash after select:', await page.evaluate(() => location.hash));
const ariaCurrent = await page.$eval('article.note[data-note-id="5"]', el => el.getAttribute('aria-current'));
console.log('aria-current on 5:', ariaCurrent);

await page.reload({ waitUntil: 'load' });
await page.waitForTimeout(100);
console.log('search value after reload:', await page.$eval('#search', el => el.value));
console.log('results-line after reload:', await page.$eval('#results-line', el => el.textContent));
const ariaCurrent2 = await page.$eval('article.note[data-note-id="5"]', el => el.getAttribute('aria-current'));
console.log('aria-current on 5 after reload:', ariaCurrent2);

await page.fill('#search', '');
await page.waitForTimeout(50);
await page.fill('#title', 'Test Note');
await page.fill('#body', 'Hello <b>world</b>\nsecond line <a href="https://example.com">link</a>');
await page.fill('#avatar', '');
await page.click('#note-form button[type=submit]');
await page.waitForTimeout(100);
const newIds = await page.$$eval('#feed article.note', els => els.map(e => e.dataset.noteId));
console.log('ids after add:', newIds);
const titleCleared = await page.$eval('#title', el => el.value);
console.log('title cleared:', JSON.stringify(titleCleared));
const maxNewId = Math.max(...newIds.map(Number));
const newBodyHtml = await page.$eval('article.note[data-note-id="' + maxNewId + '"] .note-body', el => el.innerHTML);
