await page.exposeFunction('__xss', () => { errors.push('XSS EXECUTED'); });
await page.addInitScript(() => { window.alert = () => window.__xss(); window.__hit = () => window.__xss(); });

// ---- seed + feed
await page.goto(base, { waitUntil: 'load' });
ok('seeds 6 notes', (await page.$$('#feed article.note')).length === 6);
const ids = await page.$$eval('#feed article.note', (a) => a.map((n) => n.dataset.noteId));
ok('newest first', JSON.stringify(ids) === JSON.stringify(['6','5','4','3','2','1']), ids.join(','));
ok('.note-title/.note-body present', (await page.$$('.note-title')).length === 6 && (await page.$$('.note-body')).length === 6);
ok('avatars only where given', (await page.$$('img.note-avatar')).length === 3, String((await page.$$('img.note-avatar')).length));

// ---- rich text renders
ok('bold renders as <b>', await page.$eval('[data-note-id="1"] .note-body b', (e) => e.textContent.includes('OWASP')));
ok('italic renders as <i>', await page.$eval('[data-note-id="2"] .note-body i', (e) => e.textContent === 'Ribeira'));
ok('<br> renders', (await page.$$('[data-note-id="1"] .note-body br')).length === 1);
const href = await page.$eval('[data-note-id="4"] .note-body a', (e) => e.getAttribute('href'));
ok('link clickable', href === 'https://www.livrarialello.pt/', String(href));
ok('bold is visually bold', await page.$eval('[data-note-id="1"] .note-body b', (e) => {
  const w = getComputedStyle(e).fontWeight; return w === 'bold' || Number(w) >= 700;
}));

