ok('fragment has q', page.url().endsWith('#q=douro'), page.url());
await page.fill('#search', 'FRANCESINHA');
await page.waitForTimeout(120);
ok('title match, case-insensitive', (await page.$$('#feed article.note')).length === 1, String((await page.$$('#feed article.note')).length));
await page.fill('#search', '');
await page.waitForTimeout(120);
ok('empty query clears results line', (await page.textContent('#results-line')) === '');
ok('empty query clears fragment', !page.url().includes('#'), page.url());

